general_settings := class<concrete>:
    # Elimination Manager that reports kills and deaths (required).
    @editable EliminationManager : elimination_manager_device = elimination_manager_device{}
    # Points given for each elimination.
    @editable PointsPerKill : int = 15
    # Points taken when the player dies (enter a positive number).
