# multiplayer_teleporter.verse
# Summary: Teleports all non-triggering players in the playspace to the position of the
# player who activated the linked TriggerDevice, so the whole group stays together in the
# action. If an individual teleport fails (no valid destination space found), that player
# simply remains where they are; this is logged for debugging but does not block the rest
# of the group teleport.
# Last modified: 2026-09-23 — v3 (T-006: completed the previously truncated TeleportPlayers
# if-block that caused a compile failure/stale build; dropped the <transacts> effect specifier
# on TeleportPlayers, which conflicted with Log()'s no_rollback effect, per uefn-lessons)

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /Fortnite.com/Playspaces }
using { /Fortnite.com/Characters }
using { /UnrealEngine.com/Temporary/SpatialMath }
using { /UnrealEngine.com/Temporary/Diagnostics }

# Centralized logging (see ~/.claude/CLAUDE.md rule 2) — use Log() instead of Print() directly.
@editable DebugLoggingEnabled : logic = true
Log(LogMessage : string):void=
    if (DebugLoggingEnabled?):
        Print(LogMessage)

# This device is used to handle teleporting players around the map to ensure all players are always in the action!
multiplayer_teleporter := class(creative_device):

    #The trigger device used to initiate teleporting players
    @editable
    TriggerDevice : trigger_device = trigger_device{}

    # The world axis in which the offset is applied to the teleporting character i.e. X: 0 Y:1 Z:0 will apply the offset in the Y axis
    @editable
    TeleportOffsetAxis : vector3 = vector3{X := 0.0, Y := 1.0, Z := 0.0}

    # Runs when the device is started in a running game
    OnBegin<override>()<suspends> : void=
        TriggerDevice.TriggeredEvent.Subscribe(TeleportPlayers)

    # Group-teleport logic: brings every other player in the playspace to the triggering player
    TeleportPlayers(TriggeringAgent : ?agent) : void =

        # Check if the triggering player's agent is valid and then use it's FortCharacter to set TriggeringCharacter
        if (TriggeringCharacter := TriggeringAgent?.GetFortCharacter[]):
            var TeleportOffset : float = 0.0
            CurrentPlayers := GetPlayspace().GetPlayers()
            # Iterate through all of the players, checking to make sure they aren't the triggering player, then teleport them to the triggering player
            for (Player : CurrentPlayers, Player.GetFortCharacter[] <> TriggeringCharacter, CharacterToTeleport := Player.GetFortCharacter[]):
                set TeleportOffset += 100.0
                # Teleport PlayerToTeleport to TriggeringPlayer's position, if the teleport fails to find the required space, players will remain where they are
                if (CharacterToTeleport.TeleportTo[TriggeringCharacter.GetTransform().Translation + (TeleportOffsetAxis * TeleportOffset),
                TriggeringCharacter.GetTransform().Rotation]):
                    Log("multiplayer_teleporter: successfully teleported a player to the triggering player's position.")
                else:
                    # Teleport failed (no valid destination space found) — player stays where they are, by design.
                    Log("multiplayer_teleporter: teleport failed for a player, they remain at their current position.")

# Tag_collector_device.verse
# Summary: Standalone tag_collector_device creative_device — finds all collectible_object_device
# actors tagged per each configured collectible_tag_config, wires their CollectedEvent to fire a
# dedicated trigger and respawn (fixed delay or an external timer's SuccessEvent). Independent
# device, not currently wired into game_manager's LOOP 100 loop — see SPEC.md "To confirm with
# the owner."
# Last modified: 2026-09-04 — v2
# same UEFN editor UX fix already applied to Xp_manager.verse's xp_reward_tier (new array elements
# couldn't be immediately selected/expanded in the Details panel with struct<concrete>). Usage
# audit: CollectibleConfigs is only read (never mutated/compared by value) elsewhere in this file,
# so switching to per-reference semantics is safe here.
#
using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }
using { /Verse.org/Simulation/Tags }

# --- 1. DEFINIZIONE TAG INDIPENDENTI ---
collectable_tag := class(tag){} 
Lobby_collectible_tag := class(tag){}
Vault_collectible_tag := class(tag){}
TempShop_collectible_tag := class(tag){}
endgame_collectible_tag := class(tag){}
AFK_collectible_tag := class(tag){}

# --- 2. CLASS PER LE CONFIGURAZIONI DEI TAG ---
# Usiamo il qualificatore <concrete> per consentire all'editor UEFN di mostrare l'elemento nel pannello Details.
# class<concrete> (invece di struct<concrete>) + @editable_container: AllowReordering sotto, per
# evitare il bug editor UEFN per cui i nuovi elementi aggiunti a un array di struct<concrete> non
# sono subito selezionabili/espandibili nel Details panel.
collectible_tag_config := class<concrete>:
    @editable
    CollectibleTag : subtype(tag) = collectable_tag
    @editable
    MyTrigger : trigger_device = trigger_device{}
    @editable
    UseExternalTimer : logic = false
    @editable
    ExternalTimer : timer_device = timer_device{}
    @editable
    RespawnDelay : float = 5.0

# --- 3. HANDLER PER-OGGETTO CON RIFERIMENTO ALLA CONFIGURAZIONE ---
collectible_collect_handler := class():
    Manager : tag_collector_device
    Collectible : collectible_object_device
    Config : collectible_tag_config

    OnCollected(Agent : agent) : void =
        Manager.HandleSingleCollect(Agent, Collectible, Config)

# --- 4. DEVICE PRINCIPALE ---
tag_collector_device := class(creative_device):

    # Array editable contenente le varie configurazioni di tag definite nella class
    @editable_container:
        AllowReordering := true
    @editable
    CollectibleConfigs : []collectible_tag_config = array{}

    var AllCollectibles : []collectible_object_device = array{}

    @editable
    DebugLoggingEnabled : logic = true

    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    OnBegin<override>()<suspends> : void =
        # Cicla su tutte le configurazioni inserite nell'editor
        for (Config : CollectibleConfigs):
            TaggedObjects := Self.FindCreativeObjectsWithTag(Config.CollectibleTag)

            for (Object : TaggedObjects):
                if (Collectible := collectible_object_device[Object]):
                    set AllCollectibles += array{Collectible}
                    Handler := collectible_collect_handler{
                        Manager := Self, 
                        Collectible := Collectible,
                        Config := Config
                    }
                    Collectible.CollectedEvent.Subscribe(Handler.OnCollected)

        Log("Inizializzati {AllCollectibles.Length} oggetti totali su {CollectibleConfigs.Length} gruppi di tag.")

    HandleSingleCollect(Agent : agent, Collectible : collectible_object_device, Config : collectible_tag_config) : void =
        Config.MyTrigger.Trigger(Agent)
        Log("Raccolta confermata per il gruppo tag relativo.") 
        spawn{ RespawnSingle(Agent, Collectible, Config) }

    RespawnSingle(Agent : agent, Collectible : collectible_object_device, Config : collectible_tag_config)<suspends> : void =
        if (Config.UseExternalTimer?):
            Config.ExternalTimer.SuccessEvent.Await()
        else:
            Sleep(Config.RespawnDelay)

        Collectible.Respawn(Agent)

# weighted_loot_box.verse
# Summary: A button opens a loot box and gives one item chosen by weight (rare items come rarely).
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /Verse.org/Random }
using { /UnrealEngine.com/Temporary/Diagnostics }

weighted_loot_box := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # Granters[I] is chosen with the chance Weights[I] / (sum of all Weights). Both lists need the same length.
    @editable OpenButton : button_device = button_device{}
    @editable Granters : []item_granter_device = array{}
    @editable Weights : []int = array{}

    OnBegin<override>()<suspends>:void=
        OpenButton.InteractedWithEvent.Subscribe(OnOpened)

    OnOpened(Agent : agent):void=
        if (Index := PickIndex[], Granter := Granters[Index]):
            Granter.GrantItem(Agent)
            Log("[LOOT] gave entry {Index}")

    PickIndex()<transacts><decides>:int=
        Weights.Length = Granters.Length
        var Total : int = 0
        for (W : Weights):
            set Total += W
        Total > 0
        var Roll : int = GetRandomInt(1, Total)
        var Chosen : int = -1
        for (I -> W : Weights):
            if (Chosen < 0):
                set Roll -= W
                if (Roll <= 0):
                    set Chosen = I
        Chosen >= 0
        Chosen

# wave_director.verse
# Summary: Runs enemy waves in order: one spawner for each wave, next wave after the last enemy is eliminated, with a pause between waves.
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

wave_director := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # WaveSpawners[I] spawns wave I; EnemiesPerWave[I] is how many enemies that spawner makes (set the same number on the device).
    @editable WaveSpawners : []wildlife_spawner_device = array{}
    @editable EnemiesPerWave : []int = array{}
    @editable SecondsBetweenWaves : float = 8.0
    @editable WaveHud : hud_message_device = hud_message_device{}

    var Alive : int = 0

    WaveText<localizes>(Number : int, Total : int) : message = "Wave {Number} / {Total}"
    DoneText<localizes> : message = "All waves cleared!"

    OnBegin<override>()<suspends>:void=
        for (Spawner : WaveSpawners):
            Spawner.Disable()
            Spawner.EliminatedEvent.Subscribe(OnEnemyEliminated)
        Sleep(SecondsBetweenWaves)
        for (I -> Spawner : WaveSpawners):
            if (Count := EnemiesPerWave[I]):
                set Alive = Count
                WaveHud.SetText(WaveText(I + 1, WaveSpawners.Length))
                WaveHud.Show()
                Spawner.Enable()
                Log("[WAVE] wave {I + 1} started with {Count} enemies")
                loop:
                    if (Alive <= 0):
                        break
                    Sleep(0.5)
                Spawner.Disable()
                Sleep(SecondsBetweenWaves)
        WaveHud.SetText(DoneText)
        WaveHud.Show()
        Log("[WAVE] all waves cleared")

    OnEnemyEliminated(Result : device_ai_interaction_result):void=
        if (Alive > 0):
            set Alive -= 1

# currency_shop.verse
# Summary: Every player earns money over time and can buy one reward from a button; the money is checked in Verse before anything is given.
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

currency_shop := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    @editable BuyButton : button_device = button_device{}
    @editable Reward : item_granter_device = item_granter_device{}
    @editable MoneyHud : hud_message_device = hud_message_device{}
    @editable Price : int = 100
    @editable IncomePerSecond : int = 5

    var Money : [player]int = map{}

    MoneyText<localizes>(Amount : int) : message = "Money: {Amount}"
    NotEnoughText<localizes> : message = "Not enough money"

    OnBegin<override>()<suspends>:void=
        BuyButton.InteractedWithEvent.Subscribe(OnBuy)
        loop:
            Sleep(1.0)
            for (P : GetPlayspace().GetPlayers()):
                AddMoney(P, IncomePerSecond)

    GetMoney(P : player)<transacts>:int=
        if (Value := Money[P]):
            return Value
        0

    AddMoney(P : player, Amount : int):void=
        if (set Money[P] = GetMoney(P) + Amount):
            MoneyHud.Show(P, MoneyText(GetMoney(P)))

    OnBuy(Agent : agent):void=
        if (P := player[Agent]):
            if (GetMoney(P) >= Price):
                AddMoney(P, -Price)
                Reward.GrantItem(Agent)
                Log("[SHOP] bought for {Price}")
            else:
                MoneyHud.Show(P, NotEnoughText)

# persistent_levels.verse
# Summary: Experience points are saved for each player between sessions and turned into a level with a table of thresholds.
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

progress_data := class<final><persistable>:
    Version : int = 1
    Xp : int = 0

var SavedProgress : weak_map(player, progress_data) = map{}

persistent_levels := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    @editable AwardButton : button_device = button_device{}
    @editable Hud : hud_message_device = hud_message_device{}
    @editable XpPerPress : int = 25
    # XP needed to reach level 2, 3, 4 ... in rising order
    @editable LevelThresholds : []int = array{100, 250, 450, 700}

    LevelText<localizes>(Level : int, Xp : int) : message = "Level {Level}   XP {Xp}"

    OnBegin<override>()<suspends>:void=
        AwardButton.InteractedWithEvent.Subscribe(OnAward)

    GetXp(P : player):int=
        if (Data := SavedProgress[P]):
            return Data.Xp
        0

    LevelFor(Xp : int):int=
        var Level : int = 1
        for (Needed : LevelThresholds):
            if (Xp >= Needed):
                set Level += 1
        Level

    OnAward(Agent : agent):void=
        if (P := player[Agent]):
            NewXp := GetXp(P) + XpPerPress
            if (set SavedProgress[P] = progress_data{Version := 1, Xp := NewXp}):
                Hud.Show(P, LevelText(LevelFor(NewXp), NewXp))
                Log("[XP] {NewXp}")

# hunger_needs.verse
# Summary: Hunger falls slowly for every player, a button restores it, and an empty bar hurts a little each second instead of killing at once.
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Fortnite.com/Characters }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

hunger_needs := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    @editable FoodButton : button_device = button_device{}
    @editable Hud : hud_message_device = hud_message_device{}
    @editable HungerLossPerSecond : float = 1.0
    @editable StarveDamagePerSecond : float = 2.0
    @editable FoodRestores : float = 40.0

    var Hunger : [player]float = map{}

    HungerText<localizes>(Percent : int) : message = "Hunger {Percent}"

    OnBegin<override>()<suspends>:void=
        FoodButton.InteractedWithEvent.Subscribe(OnEat)
        loop:
            Sleep(1.0)
            for (P : GetPlayspace().GetPlayers()):
                Tick(P)

    Current(P : player)<transacts>:float=
        if (Value := Hunger[P]):
            return Value
        100.0

    Tick(P : player):void=
        Next := Max(0.0, Current(P) - HungerLossPerSecond)
        if (set Hunger[P] = Next, Percent := Floor[Next]):
            Hud.Show(P, HungerText(Percent))
        if (Next <= 0.0, Character := P.GetFortCharacter[]):
            Character.Damage(StarveDamagePerSecond)
            Log("[NEEDS] starving")

    OnEat(Agent : agent):void=
        if (P := player[Agent]):
            if (set Hunger[P] = Min(100.0, Current(P) + FoodRestores)):
                Log("[NEEDS] ate")

# ordered_objectives.verse
# Summary: Triggers must be touched in order (quest steps or course checkpoints); each player has own progress and out of order touches are ignored.
# Last modified: 2026-10-30 - v1

using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }

objective_listener := class:
    Owner : ordered_objectives
    Index : int

    OnTriggered(MaybeAgent : ?agent):void=
        if (Agent := MaybeAgent?):
            Owner.Reached(Index, Agent)

ordered_objectives := class(creative_device):

    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # Steps[0] is the first step, Steps[1] the second, and so on
    @editable Steps : []trigger_device = array{}
    @editable Hud : hud_message_device = hud_message_device{}

    var Progress : [player]int = map{}
    var Listeners : []objective_listener = array{}

    StepText<localizes>(Done : int, Total : int) : message = "Steps {Done} / {Total}"
    DoneText<localizes> : message = "All steps done!"

    OnBegin<override>()<suspends>:void=
        for (I -> Step : Steps):
            Listener := objective_listener{Owner := Self, Index := I}
            set Listeners += array{Listener}
            Step.TriggeredEvent.Subscribe(Listener.OnTriggered)

    DoneFor(P : player):int=
        if (Value := Progress[P]):
            return Value
        0

    Reached(Index : int, Agent : agent):void=
        if (P := player[Agent]):
            Done := DoneFor(P)
            if (Index = Done):
                if (set Progress[P] = Done + 1):
                    Log("[STEPS] step {Done + 1}")
                    if (Done + 1 >= Steps.Length):
                        Hud.Show(P, DoneText)
                    else:
                        Hud.Show(P, StepText(Done + 1, Steps.Length))

# CurrencyUIAnimation.verse
# Summary: Standalone, self-contained currency-earn VFX device. Owns its own set of internal
#   Animated_UI widgets (Small/Medium/Large amount variants) and shows a randomly chosen one to
#   the triggering player whenever it's told to. Deliberately independent from GameManager and
#   coin_display_manager.verse (see project memory feedback_coin_display_manager_independence,
#   T-023 third attempt): this device is never called BY GameManager and never calls INTO it —
#   it reacts on its own to native Trigger devices via its own trigger arrays.
# Last modified: 2026-10-02 - v11 (T-094: header condensed to the 15-line cap)
#   pop-up with a per-trigger material Icon (Icon field bound to every Image brush in the 9 Animated_UI widgets). Category config
#   went through fixed slots (rejected) and struct fields (rejected) to the final form: ONE @editable []currency_category where
#   currency_category is a class<concrete> (Icon : ?material, Triggers : []trigger_device) - verified live via MCP, expandable in
#   the Details panel, no Verse change to add a currency. B-009 added diagnostic logs (index-0 icon report; material is not
#   comparable in Verse so identity checks are impossible - runtime logs are the evidence).
using { /Fortnite.com/Devices }
using { /Verse.org/Simulation }
using { /UnrealEngine.com/Temporary/Diagnostics }
using { /UnrealEngine.com/Temporary/UI }
using { /Verse.org/Colors }
using { /Verse.org/Random }
using { /Verse.org/Assets }


S2M<localizes>(Name : string) : message = "+${Name}"

# --- Currency category: one icon + one arbitrarily-expandable trigger array (T-028 v7) ---
# class<concrete>, NOT a struct: this is the key shape difference from the rejected v6 attempt.
# Any trigger in Triggers firing shows Icon's currency animation. The device exposes a SINGLE
# @editable []currency_category array (CurrencyCategories below) — the owner populates it with
# as many categories (coin, diamond, future currencies) as needed directly in UEFN's Details
# panel, no fixed/named slots and no Verse change required to add one.
currency_category := class<concrete>:
    @editable
    Icon : ?material = false

    @editable
    Triggers : []trigger_device = array{}

# Per-entry Subscribe target: Verse doesn't support a locally-scoped named function or bare
# lambda literal inside a for-loop body, so each trigger entry gets one small listener object
# that remembers which device + which icon it's responsible for.
currency_trigger_listener := class:
    Device : CurrencyUIAnimation
    Icon : material
    CategoryIndex : int  # diagnostic only (B-009) — which CurrencyCategories entry this came from

    OnTriggered(MaybeAgent : ?agent) : void =
        # T-092: guard before string interpolation (hot path, one call per earn trigger).
        if (Device.DebugLoggingEnabled?):
            Device.Log("CurrencyUIAnimation: trigger fired for category {CategoryIndex} -> forwarding its configured Icon")
        if (Agent := MaybeAgent?):
            Device.ShowRandomCurrencyAnim(Agent, Icon)

CurrencyUIAnimation := class(creative_device):

    # --- Logging (rule 2 — centralized logger, no direct Print() calls) ---
    @editable DebugLoggingEnabled : logic = true
    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # --- Device references ---
    # TestBtn: manual/dev-testing entry point, pre-existing, kept as-is.
    @editable TestBtn : button_device = button_device{}

    # Currency categories (T-028 v7): a single arbitrary-length array of currency_category
    # class instances, each with its own Icon and its own expandable Triggers array. Populate
    # directly in the Details panel — one entry per currency (coin, diamond, future ones), no
    # fixed count and no Verse change needed to add another.
    @editable
    CurrencyCategories : []currency_category = array{}

    @editable MaxSmallAmount : int = 0
    @editable MaxMediumAmount : int = 0
    @editable MaxLargeAmount : int = 0
    @editable TextColor : color = color{}

    # B-014 fix: how long a currency pop-up widget stays visible before being removed. Matches the
    # animation length; tune in the Details panel if the animation timing changes.
    @editable WidgetDisplayDuration : float = 3.0

    # T-092: max simultaneously visible currency pop-ups per player (kills/rewards in quick
    # succession would otherwise stack one widget + one spawned cleanup task per earn event for
    # WidgetDisplayDuration seconds each). weak_map: entries drop automatically when a player leaves.
    @editable MaxConcurrentWidgetsPerPlayer : int = 8
    var ActiveWidgetCount : weak_map(player, int) = map{}

    # --- Setup ---
    OnBegin<override>()<suspends>:void=
        TestBtn.InteractedWithEvent.Subscribe(OnTestBtnInteracted)
        var TotalTriggers : int = 0
        var CategoryIndex : int = 0
        for (Category : CurrencyCategories):
            set CategoryIndex += 1
            Count := SubscribeCategory(Self, Category, CategoryIndex)
            set TotalTriggers += Count
            Log("CurrencyUIAnimation: category {CategoryIndex} -> {Count} trigger(s)")
        Log("CurrencyUIAnimation: ready -> {CurrencyCategories.Length} categor(y/ies), {TotalTriggers} trigger(s) total + TestBtn")
        # B-009 diagnostic: `material` isn't a `comparable` type in Verse, so a direct identity
        # check between two categories' Icon fields (e.g. to catch a UEFN Details-panel instanced
        # subobject aliasing bug) can't be written here — the "category N has no Icon" log above,
        # plus the per-trigger logs below, are the runtime evidence this investigation relies on
        # instead: if category 1 (coin) never logs "no Icon", its listener IS wired with a real
        # Icon reference, which narrows the bug away from "Icon field empty" and points at either
        # a wrong (but non-empty) Icon asset assigned in the Details panel, or a widget-side issue.

    # Wires every trigger in a currency_category's Triggers array to fire with that category's
    # Icon. Returns how many triggers were actually subscribed (skipped if Icon isn't set yet).
    # CategoryIndex is diagnostic-only (B-009), threaded into the listener so OnTriggered can log
    # which configured category actually fired.
    SubscribeCategory(Device : CurrencyUIAnimation, Category : currency_category, CategoryIndex : int) : int =
        var Count : int = 0
        if (CategoryIcon := Category.Icon?):
            for (Trigger : Category.Triggers):
                Listener : currency_trigger_listener = currency_trigger_listener{Device := Device, Icon := CategoryIcon, CategoryIndex := CategoryIndex}
                Trigger.TriggeredEvent.Subscribe(Listener.OnTriggered)
                set Count += 1
        else:
            Log("CurrencyUIAnimation: category {CategoryIndex} has trigger(s) configured but no Icon — skipped")
        Count

    # --- Entry points ---
    # Manual test path: uses the first configured category's icon for a quick sanity check.
    OnTestBtnInteracted(Agent:agent):void=
        if (FirstCategory := CurrencyCategories[0]):
            if (FirstIcon := FirstCategory.Icon?):
                ShowRandomCurrencyAnim(Agent, FirstIcon)
            else:
                Log("CurrencyUIAnimation: TestBtn pressed but CurrencyCategories[0] has no Icon configured")
        else:
            Log("CurrencyUIAnimation: TestBtn pressed but CurrencyCategories is empty — add at least one category")

    # --- Shared widget-picking logic (unchanged tier/variant selection from T-023, now also
    # threading the per-trigger Icon into whichever widget gets picked) ---
    ShowRandomCurrencyAnim(Agent:agent, Icon:material):void=
        if (DebugLoggingEnabled?):
            Log("CurrencyUIAnimation: ShowRandomCurrencyAnim called, constructing widget with the Icon forwarded by the firing trigger")
        var CurrencyWidget : widget = Animated_UI.Animated_UI_Widget_LargeAmount1{Icon := Icon}
        if(Player := player[Agent], PlayerUI := GetPlayerUI[Player]):
            # T-092: per-player cap on simultaneously visible pop-ups (each lives WidgetDisplayDuration
            # seconds). Over the cap the pop-up is skipped - purely cosmetic, the reward is unaffected.
            ActiveCount := if (N := ActiveWidgetCount[Player]) then N else 0
            if (ActiveCount >= MaxConcurrentWidgetsPerPlayer):
                if (DebugLoggingEnabled?):
                    Log("CurrencyUIAnimation: pop-up skipped, {ActiveCount} already active for this player (cap {MaxConcurrentWidgetsPerPlayer})")
                return
            if (set ActiveWidgetCount[Player] = ActiveCount + 1) {}
            RandomValIndex := GetRandomInt(1,3)
            RandomValText := GetRandomInt(0,MaxLargeAmount)
            if(RandomValText <= MaxSmallAmount):
                if(RandomValIndex = 1):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_SmallAmount1{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
                else if(RandomValIndex = 2):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_SmallAmount2{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
                else if(RandomValIndex = 3):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_SmallAmount3{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
            else if(RandomValText <= MaxMediumAmount):
                if(RandomValIndex = 1):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_MediumAmount1{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
                else if(RandomValIndex = 2):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_MediumAmount2{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
                else if(RandomValIndex = 3):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_MediumAmount3{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
            else if(RandomValText <= MaxLargeAmount):
                if(RandomValIndex = 1):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_LargeAmount1{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
                else if(RandomValIndex = 2):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_LargeAmount2{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
                else if(RandomValIndex = 3):
                    set CurrencyWidget = Animated_UI.Animated_UI_Widget_LargeAmount3{Amount_Text:=S2M("{RandomValText}"),Text_Color := TextColor,Icon := Icon}
            PlayerUI.AddWidget(CurrencyWidget)
            # B-014 fix: schedule cleanup instead of leaving the widget added forever.
            spawn:
                CleanupCurrencyWidget(Player, PlayerUI, CurrencyWidget)

    # --- Widget lifecycle cleanup (B-014 fix) ---
    # Same spawn/Sleep/RemoveWidget shape as daily_quests_device.verse's ManageQuestWidget: wait
    # for the pop-up's on-screen duration, then remove it, so widgets never accumulate. PlayerUI
    # and CurrencyWidget are captured per-call, so concurrent calls for different players (or the
    # same player earning currency again before this one finishes) each clean up their own widget
    # independently.
    CleanupCurrencyWidget(Player:player, PlayerUI:player_ui, CurrencyWidget:widget)<suspends>:void=
        Sleep(WidgetDisplayDuration)
        PlayerUI.RemoveWidget(CurrencyWidget)
        # T-092: release this pop-up's slot in the per-player cap.
        if (N := ActiveWidgetCount[Player]):
            if (set ActiveWidgetCount[Player] = Max(0, N - 1)) {}

# GameManager.verse
# Summary: Central horror co-op Game Manager. Drives the infinite round loop via an explicit
#   state machine (Waiting -> Preparing (round 1 only) -> RoundActive -> Intermission -> loop,
#   Resetting reachable from any state at 0 active players), tracks 1-4 players, scales the
#   zombie/NPC horde (and hive/boss events) with round number via native spawner devices, ends the
#   round early if all players go down, and awards gold + XP per kill and diamonds per round
#   completed. It exposes NO public gold read/spend API (removed, see v19/T-001 below): balances
#   live in EconomyLedger (economy_ledger.verse). It only fires KillTrigger/RoundCompleteTrigger/
#   DiamondEarnedTrigger/RoundStartTrigger and the GoldAwardedEvent/DiamondsAwardedEvent signals
#   for independent modules (PrestigeManager, CurrencyUIAnimation, LeaderboardManager, ...) to
#   react to - GameManager never calls into those modules (standing decoupling rule, v21).
# Last modified: 2026-11-05 - v57
using { /Fortnite.com/Devices }
using { /Fortnite.com/Game }
using { /Fortnite.com/Characters }
using { /Verse.org/Simulation }
using { /Verse.org/Simulation/Tags }
using { /Verse.org/Random }
using { /UnrealEngine.com/Temporary/Diagnostics }
using { /UnrealEngine.com/Temporary/UI }
using { BossManager }
using { HiveManager }
using { big_number_utils }
using { player_state_utils }

# T-044: system-broadcast messages for round start/end, shown via RoundMessageDevice's
# no-Agent Show(Message, ?DisplayTime) overload (broadcasts to all players). `message` fields
# aren't individually editable, so this follows the same <localizes>-wrapper-function pattern
# already used by AreaUnlockManager.AreaUnlockedMessage/CreatorMessageManager.CreatorMessageText.
RoundStartMessage<public><localizes>:message = "THEY ARE COMING"
RoundSurviveMessage<public><localizes>:message = "WELL DONE, YOU SURVIVE"
# T-062: boss-round and hive-invasion round-start variants, same wrapper pattern and same
# 5s ?DisplayTime as RoundStartMessage - shown instead of it depending on what kind of round
# is starting (see the three-way choice in RunGameLoop).
BossRoundMessage<public><localizes>:message = "DEFEAT THE BOSS TO COMPLETE THE ROUND"
HiveInvasionMessage<public><localizes>:message = "INVASION! PROTECT YOURSELF"

# Game state enum for the central state machine.
game_state := enum:
    Waiting
    Preparing
    RoundActive
    Intermission
    Resetting

# Small relay object bound one-per-pool to ZombieSpawnerPools[Index].EliminatedEvent, so the
# shared game_manager.OnZombieEliminated handler can know which pool tier actually fired
# (Subscribe alone can't tell pools apart when the same function is bound to all of them).
# See Bug #2 fix, v6 header note.
zombie_kill_relay := class:
    Manager : game_manager
    PoolIndex : int
    OnEliminated(Result : device_ai_interaction_result) : void=
        Manager.OnZombieEliminated(Result, PoolIndex)

# T-058: NPC-pool equivalent of zombie_kill_relay above. npc_spawner_device has no
# EliminatedEvent of its own (see this file's v33 header note), so this relay is bound to the
# spawner's SpawnedEvent instead - one per NPC pool, carrying the same fixed PoolIndex scheme
# already used for the zombie pools (main pool index = array index, random pool index =
# ZombieSpawnerPools.Length + array index). Each spawn starts its own async elimination watcher.
npc_kill_relay := class:
    Manager : game_manager
    PoolIndex : int
    OnSpawned(Agent : agent) : void=
        # DIAG (BUGS.md, 2026-09-24): confirms an NPC spawn actually reached this relay and
        # for which PoolIndex, before TrackNpcKill's own async watcher starts.
        if (Manager.DiagLoggingEnabled?):
            Manager.Log("GameManager[NPC-DIAG]: npc_kill_relay.OnSpawned fired for PoolIndex={PoolIndex}, starting TrackNpcKill")
        spawn{ Manager.TrackNpcKill(Agent, PoolIndex) }

game_manager<public> := class(creative_device):

    # Centralized logger (see Claude/reference/logger-template.verse.txt). Must be a class
    # member, not a file-level function/field - a file-level @editable does NOT appear as a
    # configurable property in the Details panel for the placed device instance, even though
    # it compiles fine (v18 fix, see project memory).
    @editable DebugLoggingEnabled : logic = true
    # T-092: separate switch for the high-frequency [NPC-DIAG]/[KILL-DIAG]/[SIGNAL-DIAG] instrumentation
    # (per-kill / per-signal lines); the call sites guard on it BEFORE the string is interpolated.
    @editable DiagLoggingEnabled : logic = false
    Log(LogMessage : string) : void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    # ================================================================================
    # --- Group: Timers (native devices orchestrated by the round loop) ---
    # ================================================================================
    @editable PreparationTimer : timer_device = timer_device{}
    @editable RoundTimer : timer_device = timer_device{}
    @editable IntermissionTimer : timer_device = timer_device{}

    # ================================================================================
    # --- Group: Economy (gold/XP/diamonds tuning - horde_scaler-independent) ---
    # ================================================================================
    # Gold reward per zombie/NPC kill: BaseGoldPerKill for pool 0, +GoldPerKillStep for every
    # subsequent pool index (linear/arithmetic progression BaseGoldPerKill + GoldPerKillStep *
    # PoolIndex), so any number of placed pools scales automatically with no fixed-size array
    # to keep in sync (replaces the old GoldPerKillByPool array + out-of-range fallback, v8).
    # Round number also adds a flat +2*CurrentRound bonus (see AwardAndSignalKill) so later
    # rounds pay out more even from the same pool. T-058: NPC pool kills use this exact same
    # formula against the equivalent zombie pool's PoolIndex - no separate NPC tuning.
    @editable BaseGoldPerKill : int = 5
    @editable GoldPerKillStep : int = 5
    @editable XPPerKill : int = 15
    @editable DiamondsPerRoundCompleted : int = 5

    # ================================================================================
    # --- Group: Horde - Zombie (horde_scaler.verse's main + random creature pools) ---
    # ================================================================================
    # Tiered zombie spawner pools: index 0 enabled from round 1, index 1 from round 3,
    # index 2 from round 5, etc. (see ScalingNote below). Uses the native Creature Spawner
    # device's Enable/Disable/EliminateCreatures API so quantity/variety scale by how many
    # pools are active per round, and kills are reported per pool via EliminatedEvent.
    @editable ZombieSpawnerPools : []creature_spawner_device = array{}

    # Extra zombie pools with RANDOM activation (v9, was a single field in v8), separate from
    # ZombieSpawnerPools so they never enter the deterministic 1+2*Index activation formula or
    # the per-index gold tier for the array above. From RandomPoolMinRound onward, EVERY round
    # each element of this array independently rolls its own RandomPoolActivationChance chance
    # to enable for that round (see horde_scaler.EnableHordeForRound) - one spawner rolling doesn't affect
    # any other. The owner has 7 physical Creature Spawner devices to assign here (see final
    # report) - any number can be added/removed later without further code changes.
    @editable RandomZombieSpawnerPools : []creature_spawner_device = array{}
    @editable RandomPoolMinRound : int = 3
    @editable RandomPoolActivationChance : float = 0.3

    # T-058: independently gates ZombieSpawnerPools/RandomZombieSpawnerPools without affecting
    # the NPC toggles below - both can be true (mixed zombie+NPC horde), either alone, or both
    # off. Default true so the current live island's behavior is unchanged.
    @editable EnableZombieMainPool : logic = true
    @editable EnableZombieRandomPool : logic = true

    # ================================================================================
    # --- Group: Horde - Npc (T-058 themed-clone parallel to the zombie pools above -
    #     e.g. Star Wars troopers/K-pop dancers instead of zombies, same activation math) ---
    # ================================================================================
    @editable NpcSpawnerPools : []npc_spawner_device = array{}
    @editable RandomNpcSpawnerPools : []npc_spawner_device = array{}
    @editable EnableNpcMainPool : logic = true
    @editable EnableNpcRandomPool : logic = true

    # ================================================================================
    # --- Group: Horde - Guard (T-098: guard_spawner_device pools, parallel to the zombie/NPC pools -
    #     same activation math, kills paid like the equivalent zombie pool index; no HP scaling) ---
    # ================================================================================
    @editable GuardSpawnerPools : []guard_spawner_device = array{}
    @editable RandomGuardSpawnerPools : []guard_spawner_device = array{}
    @editable EnableGuardMainPool : logic = true
    @editable EnableGuardRandomPool : logic = true

    # ================================================================================
    # --- Group: Hive (hive_scaler.verse) - two independently-rolling wildlife pools plus a
    #     separate "invasion" roll, mirroring horde_scaler's own two-pool shape. Explicitly NOT
    #     tied to TimedEventsManager - see hive_scaler.verse's own header. ---
    # ================================================================================
    @editable HiveSpawnerPools : []wildlife_spawner_device = array{}
    @editable InvasionSpawnerPools : []wildlife_spawner_device = array{}
    @editable HiveMinRound : int = 5
    @editable HivePoolActivationChance : float = 0.3
    @editable InvasionChance : float = 0.1
    # T-058: single on/off for the whole hive system (no type split - animals aren't swappable
    # for another device type, confirmed by owner). Default true, unchanged live behavior.
    @editable EnableHive : logic = true

    # ================================================================================
    # --- Group: Boss (boss_event_manager.verse) - see that file's own header for the full
    #     mechanic and the guard_device -> guard_spawner_device technical-risk resolution.
    #     KEPT as guard_spawner_device (2026-09-20 bug-fix review, BUGS.md): unlike
    #     NpcSpawnerPools/RandomNpcSpawnerPools above, this pool's HP/shield round-scaling
    #     (T-030 AC) reads/writes MaxHealth/InitialHealth/MaxShield/InitialShield, fields that
    #     exist on guard_spawner_device but NOT on npc_spawner_device (confirmed live via
    #     Fortnite.digest.verse) - switching this one would silently drop boss HP scaling. ---
    # ================================================================================
    @editable BossPool : []guard_spawner_device = array{}
    @editable MinBossGap : int = 5
    @editable MaxBossGap : int = 10
    @editable BossScalingFactor : float = 0.1
    @editable BaseMultiBossChance : float = 0.0
    @editable MultiBossGrowthRate : float = 0.005
    @editable MaxMultiBossChance : float = 0.6
    # T-058: single on/off for the whole boss system - when false, no boss round is ever
