        Items

    SignalGoldAwarded(Agent : agent, Amount : int) : void=
        if (LeaderboardGoldQueue.Length >= MaxAwardQueueLength):
            set LeaderboardGoldQueue = array{}
        if (PartyGoldQueue.Length >= MaxAwardQueueLength):
            set PartyGoldQueue = array{}
        set LeaderboardGoldQueue += array{(Agent, Amount)}
        set PartyGoldQueue += array{(Agent, Amount)}
        set GoldSignalsSent += 1
        if (DiagLoggingEnabled?):
            Log("GameManager[SIGNAL-DIAG]: GoldAwardedEvent sent #{GoldSignalsSent} amount={Amount}")
        GoldAwardedEvent.Signal((Agent, Amount))

    SignalDiamondsAwarded(Agent : agent, Amount : int) : void=
        if (LeaderboardDiamondsQueue.Length >= MaxAwardQueueLength):
            set LeaderboardDiamondsQueue = array{}
        set LeaderboardDiamondsQueue += array{(Agent, Amount)}
        set DiamondsSignalsSent += 1
        if (DiagLoggingEnabled?):
            Log("GameManager[SIGNAL-DIAG]: DiamondsAwardedEvent sent #{DiamondsSignalsSent} amount={Amount}")
        DiamondsAwardedEvent.Signal((Agent, Amount))

