    # RandomPoolMinRound onward with probability RandomPoolActivationChance, independent of the
    # deterministic schedule. This gives an increasing quantity/variety curve without needing
    # per-round numeric spawn-count tuning on each device. Gold = BaseGoldPerKill +
    # GoldPerKillStep * PoolIndex, plus a flat +2-per-round bonus, so both which pool the kill
    # came from and the current round increase the payout, and any number of pools (including
    # any number of random pools, v9) scales automatically without a fixed-size lookup array.

    OnBegin<override>()<suspends> : void=
        Log("GameManager: OnBegin - initializing state machine in Waiting")
        # T-042: build the real horde_scaler/economy_ledger instances from this device's own
        # @editable fields (the placeholder archetypes above only exist to satisfy Verse's
        # "every var needs a default" rule before OnBegin runs).
        set HordeScaler = horde_scaler{
            HordeDebugLoggingEnabled := DebugLoggingEnabled,
            ZombieSpawnerPools := ZombieSpawnerPools,
            NpcSpawnerPools := NpcSpawnerPools,
