            BaseMultiBossChance := BaseMultiBossChance,
            MultiBossGrowthRate := MultiBossGrowthRate,
            MaxMultiBossChance := MaxMultiBossChance,
            EnableBossSystem := EnableBossSystem,
            BossSpawnWarningTimeout := BossSpawnWarningTimeout
