        # T-030 (1.6): this device has the creative_object_interface context boss_event_manager
        # itself lacks - see that file's header - so it's the one that does the actual per-player
        # WB_Main fan-out when the aggregate boss HP progress changes. Custom Verse `event()`
        # values don't support `.Subscribe` (only native device signals do) - same await-loop
        # pattern already established for GoldAwardedEvent/DiamondsAwardedEvent consumers
        # elsewhere in this project (see LeaderboardManager.verse/party_up_manager.verse).
        spawn{ WatchBossHpProgress() }
        GetPlayspace().PlayerAddedEvent().Subscribe(OnPlayerAdded)
        GetPlayspace().PlayerRemovedEvent().Subscribe(OnPlayerRemoved)
        # One relay per pool so OnZombieEliminated can tell which tier fired (Bug #2 fix).
        for (Index -> Spawner : ZombieSpawnerPools):
            Relay := zombie_kill_relay{Manager := Self, PoolIndex := Index}
            set KillRelays += array{Relay}
            Spawner.EliminatedEvent.Subscribe(Relay.OnEliminated)
        # Random pools (v9, array) - kept out of the loop above so they never get a progressive
        # index tied to ZombieSpawnerPools.Length changing; each gets its own relay with a
        # fixed virtual tier index continuing on from the last deterministic pool
        # (ZombieSpawnerPools.Length + Index) so every random pool's kills still pay gold
        # consistent with the same BaseGoldPerKill/GoldPerKillStep formula, without colliding
        # with the real ZombieSpawnerPools indices.
        for (Index -> Spawner : RandomZombieSpawnerPools):
            RandomPoolRelay := zombie_kill_relay{Manager := Self, PoolIndex := ZombieSpawnerPools.Length + Index}
            set KillRelays += array{RandomPoolRelay}
            Spawner.EliminatedEvent.Subscribe(RandomPoolRelay.OnEliminated)
        # T-058: NPC pool relays - npc_spawner_device has no EliminatedEvent (see this file's
        # v33 header note), so these subscribe to SpawnedEvent instead; the relay itself starts
        # an async per-agent elimination watcher (TrackNpcKill) on every spawn. Same PoolIndex
        # scheme as the zombie relays above - main pool index = array index, random pool index =
        # ZombieSpawnerPools.Length + array index - so an NPC kill pays exactly like a kill from
        # the equivalent-index zombie pool (owner's Step 0.5 tier-parity decision).
