            NpcRelay := npc_kill_relay{Manager := Self, PoolIndex := Index}
            set NpcKillRelays += array{NpcRelay}
            Spawner.SpawnedEvent.Subscribe(NpcRelay.OnSpawned)
        for (Index -> Spawner : RandomNpcSpawnerPools):
            RandomNpcRelay := npc_kill_relay{Manager := Self, PoolIndex := ZombieSpawnerPools.Length + Index}
            set NpcKillRelays += array{RandomNpcRelay}
            Spawner.SpawnedEvent.Subscribe(RandomNpcRelay.OnSpawned)
        # T-098: guard pool relays - guard_spawner_device likewise has no horde-level EliminatedEvent, so the same
        # npc_kill_relay/TrackNpcKill path is reused (SpawnedEvent -> per-agent fort_character.EliminatedEvent).
        # PoolIndex scheme identical to the zombie pools (owner decision, T-098).
        for (Index -> Spawner : GuardSpawnerPools):
            GuardRelay := npc_kill_relay{Manager := Self, PoolIndex := Index}
            set NpcKillRelays += array{GuardRelay}
            Spawner.SpawnedEvent.Subscribe(GuardRelay.OnSpawned)
        for (Index -> Spawner : RandomGuardSpawnerPools):
            RandomGuardRelay := npc_kill_relay{Manager := Self, PoolIndex := ZombieSpawnerPools.Length + Index}
            set NpcKillRelays += array{RandomGuardRelay}
            Spawner.SpawnedEvent.Subscribe(RandomGuardRelay.OnSpawned)
        # Player Spawner join/late-join signal (task 5) - supplementary logging only, see
        # field comment above.
        for (Index -> Spawner : PlayerSpawners):
            Spawner.SpawnedEvent.Subscribe(OnPlayerSpawnedAtSpawner)
        set CurrentState = game_state.Waiting
        # WB_Main / HUD fix: PlayerAddedEvent only fires for players who join AFTER this
        # Subscribe call - any player already present in the playspace when the match/device
        # starts (the common case at match start) would otherwise never get OnPlayerAdded
        # called, and so never get a WB_Main widget built. Explicitly bootstrap the HUD/state
        # for everyone already connected at OnBegin.
        for (Player : GetPlayspace().GetPlayers()):
            OnPlayerAdded(Player)
        spawn{ RunGameLoop() }
        spawn{ ResourceCounterLoop() }

    # --- v16: HUD poll loop, real-inventory source of truth for the display only ---
    # Periodically (every 0.5s, not per-tick - see v15 header note) reads each connected
    # player's physical Gold and Diamonds counts off their own dedicated Conditional Button
    # (v16: GoldCounterButton / DiamondCounterButton, each single-slot, index 0) and pushes them
