    # made from OnZombieEliminated/OnRoundCompleted.
    # T-093 (diagnostic only): per-player start time (GetSecondsSinceEpoch) of the 10 s invent

# LikeFavWorldUI.verse
# Summary: Unified Like/Favorite device supporting two modes - a World UI entity visible to all
#   players in the level, and a personal pop-up widget shown only to the interacting player.
#   Originally made by YashMaps with help from TrickTyger's World UI tutorial. The personal widget
#   is created by SetupPlayerWidget (retries every 0.25 s for up to 10 s until GetPlayerUI is
#   ready); PlayPersonalAnimationFor uses a per-player run counter so concurrent triggers do not
#   interleave; WidgetsPerPlayer and the run counter are pruned when a player leaves.
# Last modified: 2026-11-05 -- v5

using { /Verse.org }
using { /Verse.org/Native }
using { /Verse.org/SceneGraph }
using { /Verse.org/Simulation }
using { /Fortnite.com/Devices }
using { /Fortnite.com/Characters }
using { /Fortnite.com/Playspaces }
using { /UnrealEngine.com/Temporary/UI }
using { /UnrealEngine.com/Temporary/Diagnostics }
using { player_state_utils }

S2M<localizes>(value:string) : message = "{value}"

like_follow_ui_manager<public> := class(creative_device):

    # Trigger 1: Modalità World UI (Entità 3D visibile a tutti nel mondo)
    @editable 
    WorldUiTrigger : trigger_device = trigger_device{}

    # Trigger 2: Modalità Pop-up UI (Widget a schermo personale del singolo giocatore)
    @editable 
    PersonalUiTrigger : trigger_device = trigger_device{}

    @editable 
    DebugLoggingEnabled : logic = true

    Log(Msg:string):void=
        if (DebugLoggingEnabled?):
            Print("LIKEFAV_MANAGER: {Msg}")

    var WidgetsPerPlayer : [agent]WBP_LikeFavs = map{}

    OnBegin<override>()<suspends>:void=
        Log("🏷️ BUILD_TAG like_follow_ui_manager: 2026-08-04-unified-single-device")

        # Avvia l'ascolto per la modalità World UI
        spawn{ WorldUiAwait() }

        # Configura i widget personali per ogni giocatore
        GetPlayspace().PlayerAddedEvent().Subscribe(OnPlayerJoined)
        GetPlayspace().PlayerRemovedEvent().Subscribe(OnPlayerLeft)
        for (P : GetPlayspace().GetPlayers()):
            OnPlayerJoined(P)

        # Collega l'evento del Trigger personale
        PersonalUiTrigger.TriggeredEvent.Subscribe(OnPersonalTriggered)

    # ==============================================================
    # MODALITÀ 1: World UI (In-World UI condivisa)
    # ==============================================================
    WorldUiAwait()<suspends>:void=
        if:
            # FIX: Chiamata diretta a GetSimulationEntity[] valida per creative_device
            SimEnt := GetSimulationEntity[]
            Widget := first{Wid : SimEnt.FindDescendantEntities(custom_verse.LikeFavUI.WBP_LikeFavs_entity)}
        then:
            loop:
                WorldUiTrigger.TriggeredEvent.Await()

                set Widget.vText = S2M("Like")
                set Widget.vText2 = S2M("Follow")
                set Widget.vText3 = S2M("Save Island")
                set Widget.vPlayAnim = true

                Sleep(2.5)                                  # Tempo prima del primo testo
                set Widget.vText = S2M("Liked")

                Sleep(0.75)                                 # Tempo prima del secondo testo
                set Widget.vText2 = S2M("Unfollow")

                Sleep(0.75)                                 # Tempo prima del terzo testo
                set Widget.vText3 = S2M("Island Saved")

                Sleep(0.5)                                  # Coda dell'animazione
                set Widget.vPlayAnim = false
        else:
            Log("⚠️ Entità Widget World UI non trovata nella simulazione Scene Graph.")

    # ==============================================================
    # MODALITÀ 2: Pop-up Widget Personale (Per-Player UI)
    # ==============================================================
    # T-082: the personal widget is created by a coroutine that RETRIES until the player's UI is
    # ready (same idea as MapCode's WaitForScreen) - before, a single failed GetPlayerUI at join
    # meant the player never got a widget for the whole session. Gives up after ~10s or if the
    # player left meanwhile.
    OnPlayerJoined(Player:player):void=
        spawn{ SetupPlayerWidget(Player) }

    SetupPlayerWidget(Player:player)<suspends>:void=
        var Attempts : int = 0
        loop:
            if (not Player.IsActive[]):
                Log("Creazione widget personale annullata (player uscito prima che la UI fosse pronta).")
                return
            if (Agent := agent[Player], PlayerUI := GetPlayerUI[Player]):
                Widget := WBP_LikeFavs{}
                PlayerUI.AddWidget(Widget)
                if (set WidgetsPerPlayer[Agent] = Widget):
                    Log("Widget Like/Follow personale creato per un player (tentativo {Attempts + 1}).")
                else:
                    Log("⚠️ Widget creato ma non salvato in WidgetsPerPlayer.")
                return
            set Attempts += 1
            if (Attempts >= 40):
                Log("⚠️ Creazione widget personale fallita: PlayerUI non pronto dopo 10s.")
                return
            Sleep(0.25)

    # v3 (T-073): drop a departed player's widget reference so WidgetsPerPlayer doesn't grow forever.
    OnPlayerLeft(Player:player):void=
        if (Agent := agent[Player]):
            if (NewMap := WidgetsPerPlayer.WithRemovedKey(Agent)?):
                set WidgetsPerPlayer = NewMap
                Log("Widget Like/Follow personale rimosso (player uscito).")
            if (NewRuns := PersonalAnimationRun.WithRemovedKey(Agent)?):
                set PersonalAnimationRun = NewRuns

    OnPersonalTriggered(MaybeAgent:?agent):void=
        if (Agent := MaybeAgent?):
            spawn{ PlayPersonalAnimationFor(Agent) }

    # T-082: per-player run counter so two triggers for the same player don't interleave - a newer
    # run makes the older one stop (IsLatestRun fails), so the older run's final
    # `vPlayAnim = false` can no longer cut the newer animation short.
    var PersonalAnimationRun : [agent]int = map{}

    IsLatestRun(Agent:agent, Run:int)<decides><transacts>:void=
        Current := PersonalAnimationRun[Agent]
        Current = Run

    PlayPersonalAnimationFor<public>(Agent:agent)<suspends>:void=
        if (Widget := WidgetsPerPlayer[Agent]):
            var MyRun : int = 1
            if (Previous := PersonalAnimationRun[Agent]):
                set MyRun = Previous + 1
            if (set PersonalAnimationRun[Agent] = MyRun) {}

            set Widget.vText = S2M("Like")
            set Widget.vText2 = S2M("Follow")
            set Widget.vText3 = S2M("Save Island")
            set Widget.vPlayAnim = true

            Sleep(2.5)                                  # Tempo prima del primo testo
            if (not IsLatestRun[Agent, MyRun]):
                return
            set Widget.vText = S2M("Liked")

            Sleep(0.75)                                 # Tempo prima del secondo testo
            if (not IsLatestRun[Agent, MyRun]):
                return
            set Widget.vText2 = S2M("Unfollow")

            Sleep(0.75)                                 # Tempo prima del terzo testo
            if (not IsLatestRun[Agent, MyRun]):
                return
            set Widget.vText3 = S2M("Island Saved")

            Sleep(0.5)                                  # Coda dell'animazione
            if (IsLatestRun[Agent, MyRun]):
                set Widget.vPlayAnim = false
        else:
            Log("⚠️ Nessun widget trovato per questo player: animazione saltata.")

# daily_rewards_device.verse
# Summary: One-time-per-solar-day reward device (T-020). Player opens a 7-slot reward panel via
#   a button; each day's slot becomes claimable once every StatusConfig.ClaimCooldownSeconds
#   (default 86400s = 24h) since the previous claim, granting whatever a per-day trigger_device
#   is wired to (gold/diamonds/item - configured in the Details panel, not in this file). State
#   is per-player, persisted via a <persistable> class (the 7-day layout simply cycles, no
#   streak reset), and a PlayerRemovedEvent handler drops the per-player session entries on
#   leave. Standalone device (own button, own camera, own persisted state), no GameManager
#   dependency.
# Last modified: 2026-11-05 - v5
using {/Fortnite.com/Devices}
using {/Verse.org/Assets}
using {/Verse.org/Simulation}
using { player_state_utils }
using { shared_utils }
using {/UnrealEngine.com/Temporary/UI}
using {/<Account>@fortnite.com/<Project>/custom_verse/DailyRewards/Textures}

# Centralized logger (kit rule 2) — replaces direct Print() calls
MakeDayLabel<localizes>(DayNumber:int):message = "Day {DayNumber}"

MakeClaimText<localizes>():message = "Claim"

MakeClaimedText<localizes>():message = "Claimed"

MakeLockedText<localizes>():message = "Locked"

MakeCountdownText<localizes>(HoursText:string, MinutesText:string, SecondsText:string):message = "{HoursText}h:{MinutesText}m:{SecondsText}s"

MakeCountdownTextWithoutHours<localizes>(MinutesText:string, SecondsText:string):message = "{MinutesText}m:{SecondsText}s"

MakeCountdownTextSecondsOnly<localizes>(SecondsText:string):message = "{SecondsText}s"

MakeDescriptionText<localizes>(DescriptionText:string):message = "{DescriptionText}"

DailyRewardsDataVersion : int = 1

reward_player_state := class<final><persistable>:
    Version : int = 1
    ClaimedDays : int = 0
    NextClaimAtEpoch : float = 0.0

MakeRewardPlayerState<constructor>(OldData:reward_player_state)<transacts> := reward_player_state:
    Version := OldData.Version
    ClaimedDays := OldData.ClaimedDays
    NextClaimAtEpoch := OldData.NextClaimAtEpoch

var PlayerStates : weak_map(player, reward_player_state) = map{}

device_config := class<concrete>:
    @editable
    OpenRewardsButton : button_device = button_device{}

    @editable
    RewardsOrbitCamera : gameplay_camera_orbit_device = gameplay_camera_orbit_device{}

reward_day_config := class<concrete>:
    @editable
    RewardTexture : texture = daily_rewards_no_icon_T

    @editable
    ClaimTrigger : trigger_device = trigger_device{}

    @editable
    DescriptionText : string = ""

reward_config := class<concrete>:
    @editable
    Day1 : reward_day_config = reward_day_config{}

    @editable
    Day2 : reward_day_config = reward_day_config{}

    @editable
    Day3 : reward_day_config = reward_day_config{}

    @editable
    Day4 : reward_day_config = reward_day_config{}

    @editable
    Day5 : reward_day_config = reward_day_config{}

    @editable
    Day6 : reward_day_config = reward_day_config{}

    @editable
    Day7 : reward_day_config = reward_day_config{
    }

status_config := class<concrete>:
    @editable
    ClaimCooldownSeconds : float = 86400.0

    LockedColorId : float = 0.0

    ClaimColorId : float = 1.0

    ClaimedColorId : float = 2.0

daily_rewards_device := class(creative_device):
    # Centralized logger (kit rule 2)
    @editable
    DebugLoggingEnabled : logic = true

    Log(LogMessage : string):void=
        if (DebugLoggingEnabled?):
            Print(LogMessage)

    @editable
    DeviceConfig : device_config = device_config{}

    @editable
    RewardConfig : reward_config = reward_config{}

    @editable
    StatusConfig : status_config = status_config{}

    TotalRewardDays : int = 7

    var OpenRewardPanels : [player]logic = map{}

    OnBegin<override>()<suspends>:void =
        DeviceConfig.OpenRewardsButton.InteractedWithEvent.Subscribe(HandleOpenRewards)
        GetPlayspace().PlayerRemovedEvent().Subscribe(OnPlayerRemoved)

    # T-087: drop the departed player's "panel open" flag (persisted PlayerStates is not touched).
    OnPlayerRemoved(Player:player):void =
        CloseRewardPanel(Player)
        Log("DailyRewards: player left, OpenRewardPanels entry pruned")

    HandleOpenRewards(InteractingAgent:agent):void =
        Log("DailyRewards: [DIAG] HandleOpenRewards fired, InteractedWithEvent received")
        if (Player := player[InteractingAgent]):
            PlayerState := GetOrCreatePlayerState(Player)
            if (PlayerUI := GetPlayerUI[Player]):
                CanOpenRewardPanel := TryOpenRewardPanel(Player)
                if (CanOpenRewardPanel?):
                    RewardsWidget := WBP_Daily_Rewards:
                        daily_open_anim := 1.0

                    RewardsSlot := player_ui_slot:
                        InputMode := ui_input_mode.All
                        ZOrder := 100

                    RefreshRewardsWidget(PlayerState, RewardsWidget)
                    PlayerUI.AddWidget(RewardsWidget, RewardsSlot)
                    DeviceConfig.RewardsOrbitCamera.AddTo(InteractingAgent)
                    Log("DailyRewards: opened panel for player, ClaimedDays={PlayerState.ClaimedDays}")

                    spawn:
                        ManageRewardsWidget(InteractingAgent, Player, PlayerUI, RewardsWidget)
                else:
                    Log("DailyRewards: [WARN] [DIAG] TryOpenRewardPanel returned false, panel already marked open for this player")
            else:
                Log("DailyRewards: [WARN] [DIAG] GetPlayerUI failed for player, cannot open rewards panel")
        else:
            Log("DailyRewards: [WARN] [DIAG] player[InteractingAgent] conversion failed, InteractingAgent is not a player")

    ManageRewardsWidget(InteractingAgent:agent, Player:player, PlayerUI:player_ui, RewardsWidget:WBP_Daily_Rewards)<suspends>:void =
        race:
            block:
                RewardsWidget.button_exit_event.Await()
            block:
                loop:
                    SelectedDayPayload := RewardsWidget.button_day_event.Await()
                    HandleDayClaim(InteractingAgent, Player, RewardsWidget, SelectedDayPayload(0))
            block:
                loop:
                    if (Player.IsActive[]):
                        RefreshActiveDayWidget(Player, RewardsWidget)
                        Sleep(1.0)
                    else:
                        break

        CloseRewardPanel(Player)
        if (Player.IsActive[]):
            PlayerUI.RemoveWidget(RewardsWidget)
            DeviceConfig.RewardsOrbitCamera.RemoveFrom(InteractingAgent)

    GetOrCreatePlayerState(Player:player)<transacts>:reward_player_state =
        if (ExistingState := PlayerStates[Player]):
            if (ExistingState.Version = DailyRewardsDataVersion):
                return ExistingState

            UpdatedState := reward_player_state:
                Version := DailyRewardsDataVersion
                MakeRewardPlayerState<constructor>(ExistingState)
            if (set PlayerStates[Player] = UpdatedState):
                return UpdatedState
            return UpdatedState

        NewState := reward_player_state:
            Version := DailyRewardsDataVersion
        if (set PlayerStates[Player] = NewState):
            return NewState
        return NewState

    TryOpenRewardPanel(Player:player)<transacts>:logic =
        if (PanelAlreadyOpen := OpenRewardPanels[Player]):
            if (PanelAlreadyOpen?):
                return false

        if (set OpenRewardPanels[Player] = true):
            return true

        false

    CloseRewardPanel(Player:player)<transacts>:void =
        if (NewPanels := OpenRewardPanels.WithRemovedKey(Player)?):
            set OpenRewardPanels = NewPanels

    RefreshRewardsWidget(PlayerState:reward_player_state, RewardsWidget:WBP_Daily_Rewards):void =
        CurrentTime := GetSecondsSinceEpoch()
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 0)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 1)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 2)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 3)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 4)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 5)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, 6)

    RefreshActiveDayWidget(Player:player, RewardsWidget:WBP_Daily_Rewards):void =
        PlayerState := GetOrCreatePlayerState(Player)
        CurrentTime := GetSecondsSinceEpoch()
        ActiveDayIndex := GetClaimedDaysInCurrentWindow(PlayerState)
        ApplyDayToWidget(PlayerState, RewardsWidget, CurrentTime, ActiveDayIndex)

    ApplyDayToWidget(PlayerState:reward_player_state, RewardsWidget:WBP_Daily_Rewards, CurrentTime:float, DayIndex:int):void =
        DayNumber := GetDisplayedDayNumber(PlayerState, DayIndex)
        DayLabel := MakeDayLabel(DayNumber)
        DayTexture := GetRewardTextureForDay(DayIndex)
        DayDescriptionText := MakeDescriptionText(GetRewardDescriptionForDay(DayIndex))
        DayStatusText := GetStatusTextForDay(PlayerState, CurrentTime, DayIndex)
        DayStatusColor := GetStatusColorForDay(PlayerState, CurrentTime, DayIndex)
        DayIsClaimed := GetClaimedStateForDay(PlayerState, DayIndex)
        SetWidgetDayData(RewardsWidget, DayIndex, DayLabel, DayTexture, DayDescriptionText, DayStatusText, DayStatusColor, DayIsClaimed)

    GetDisplayedDayNumber(PlayerState:reward_player_state, DayIndex:int)<reads>:int =
        return GetWindowStartDayNumber(PlayerState) + DayIndex

    GetWindowStartDayNumber(PlayerState:reward_player_state)<reads>:int =
        if (CompletedWindows := Quotient[PlayerState.ClaimedDays, TotalRewardDays]):
            return (CompletedWindows * TotalRewardDays) + 1

        return 1

    GetClaimedDaysInCurrentWindow(PlayerState:reward_player_state)<reads>:int =
        if (ClaimedDaysInCurrentWindow := Mod[PlayerState.ClaimedDays, TotalRewardDays]):
            return ClaimedDaysInCurrentWindow

        return 0

    GetStatusTextForDay(PlayerState:reward_player_state, CurrentTime:float, DayIndex:int):message =
        ClaimedDaysInCurrentWindow := GetClaimedDaysInCurrentWindow(PlayerState)

        if (DayIndex < ClaimedDaysInCurrentWindow):
            return MakeClaimedText()

        if (DayIndex = ClaimedDaysInCurrentWindow):
            CanClaimCurrentDay := IsCurrentDayClaimable(PlayerState, CurrentTime)
            if (CanClaimCurrentDay?):
                return MakeClaimText()

            return BuildCountdownMessage(GetRemainingSeconds(PlayerState, CurrentTime))

        return MakeLockedText()

    GetStatusColorForDay(PlayerState:reward_player_state, CurrentTime:float, DayIndex:int):float =
        ClaimedDaysInCurrentWindow := GetClaimedDaysInCurrentWindow(PlayerState)

        if (DayIndex < ClaimedDaysInCurrentWindow):
            return StatusConfig.ClaimedColorId

        if (DayIndex = ClaimedDaysInCurrentWindow):
            CanClaimCurrentDay := IsCurrentDayClaimable(PlayerState, CurrentTime)
            if (CanClaimCurrentDay?):
                return StatusConfig.ClaimColorId

            return StatusConfig.LockedColorId

        return StatusConfig.LockedColorId

    GetClaimedStateForDay(PlayerState:reward_player_state, DayIndex:int)<reads>:logic =
        ClaimedDaysInCurrentWindow := GetClaimedDaysInCurrentWindow(PlayerState)
        if (DayIndex < ClaimedDaysInCurrentWindow):
            return true

        false

    IsCurrentDayClaimable(PlayerState:reward_player_state, CurrentTime:float)<reads>:logic =
        if (PlayerState.ClaimedDays = 0):
            return true

        if (CurrentTime >= PlayerState.NextClaimAtEpoch):
            return true

        false

    GetRemainingSeconds(PlayerState:reward_player_state, CurrentTime:float)<reads>:int =
        RemainingTime := PlayerState.NextClaimAtEpoch - CurrentTime
        if (RemainingTime <= 0.0):
            return 0

        if (RoundedSeconds := Ceil[RemainingTime]):
            return RoundedSeconds

        return 0

    GetFullCooldownSeconds()<reads>:int =
        if (RoundedCooldown := Int[StatusConfig.ClaimCooldownSeconds]):
            return RoundedCooldown

        return 86400

    BuildCountdownMessage(RemainingSeconds:int):message =
        if (Hours := Quotient[RemainingSeconds, 3600]):
            RemainingAfterHours := RemainingSeconds - (Hours * 3600)
            if (Minutes := Quotient[RemainingAfterHours, 60]):
                if (Seconds := Mod[RemainingAfterHours, 60]):
                    if (Hours > 0):
                        return MakeCountdownText(ZeroPad2(Hours), ZeroPad2(Minutes), ZeroPad2(Seconds))

                    if (Minutes > 0):
                        return MakeCountdownTextWithoutHours(ZeroPad2(Minutes), ZeroPad2(Seconds))

                    return MakeCountdownTextSecondsOnly(ZeroPad2(Seconds))

        return MakeCountdownTextSecondsOnly("00")

    GetRewardTextureForDay(DayIndex:int)<reads>:texture =
        if (DayIndex = 0):
            return RewardConfig.Day1.RewardTexture

        if (DayIndex = 1):
            return RewardConfig.Day2.RewardTexture

        if (DayIndex = 2):
            return RewardConfig.Day3.RewardTexture

        if (DayIndex = 3):
            return RewardConfig.Day4.RewardTexture

        if (DayIndex = 4):
            return RewardConfig.Day5.RewardTexture

        if (DayIndex = 5):
            return RewardConfig.Day6.RewardTexture

        return RewardConfig.Day7.RewardTexture

    GetRewardDescriptionForDay(DayIndex:int)<reads>:string =
        if (DayIndex = 0):
            return RewardConfig.Day1.DescriptionText

        if (DayIndex = 1):
            return RewardConfig.Day2.DescriptionText

        if (DayIndex = 2):
            return RewardConfig.Day3.DescriptionText

        if (DayIndex = 3):
            return RewardConfig.Day4.DescriptionText

        if (DayIndex = 4):
            return RewardConfig.Day5.DescriptionText

        if (DayIndex = 5):
            return RewardConfig.Day6.DescriptionText

        return RewardConfig.Day7.DescriptionText

    SetWidgetDayData(RewardsWidget:WBP_Daily_Rewards, DayIndex:int, DayLabel:message, DayTexture:texture, DayDescriptionText:message, DayStatusText:message, DayStatusColor:float, DayIsClaimed:logic):void =
        if (DayIndex = 0):
            set RewardsWidget.button_day_text_0 = DayLabel
            set RewardsWidget.button_day_txt_0 = DayTexture
            set RewardsWidget.button_desc_text_0 = DayDescriptionText
            set RewardsWidget.button_text_0 = DayStatusText
            set RewardsWidget.button_col_0 = DayStatusColor
            set RewardsWidget.button_claimed_0 = DayIsClaimed

        if (DayIndex = 1):
            set RewardsWidget.button_day_text_1 = DayLabel
            set RewardsWidget.button_day_txt_1 = DayTexture
            set RewardsWidget.button_desc_text_1 = DayDescriptionText
            set RewardsWidget.button_text_1 = DayStatusText
            set RewardsWidget.button_col_1 = DayStatusColor
            set RewardsWidget.button_claimed_1 = DayIsClaimed

        if (DayIndex = 2):
            set RewardsWidget.button_day_text_2 = DayLabel
            set RewardsWidget.button_day_txt_2 = DayTexture
            set RewardsWidget.button_desc_text_2 = DayDescriptionText
            set RewardsWidget.button_text_2 = DayStatusText
            set RewardsWidget.button_col_2 = DayStatusColor
            set RewardsWidget.button_claimed_2 = DayIsClaimed

        if (DayIndex = 3):
            set RewardsWidget.button_day_text_3 = DayLabel
            set RewardsWidget.button_day_txt_3 = DayTexture
            set RewardsWidget.button_desc_text_3 = DayDescriptionText
            set RewardsWidget.button_text_3 = DayStatusText
            set RewardsWidget.button_col_3 = DayStatusColor
            set RewardsWidget.button_claimed_3 = DayIsClaimed

        if (DayIndex = 4):
            set RewardsWidget.button_day_text_4 = DayLabel
            set RewardsWidget.button_day_txt_4 = DayTexture
            set RewardsWidget.button_desc_text_4 = DayDescriptionText
            set RewardsWidget.button_text_4 = DayStatusText
            set RewardsWidget.button_col_4 = DayStatusColor
            set RewardsWidget.button_claimed_4 = DayIsClaimed

        if (DayIndex = 5):
            set RewardsWidget.button_day_text_5 = DayLabel
            set RewardsWidget.button_day_txt_5 = DayTexture
            set RewardsWidget.button_desc_text_5 = DayDescriptionText
            set RewardsWidget.button_text_5 = DayStatusText
            set RewardsWidget.button_col_5 = DayStatusColor
            set RewardsWidget.button_claimed_5 = DayIsClaimed

        if (DayIndex = 6):
            set RewardsWidget.button_day_text_6 = DayLabel
            set RewardsWidget.button_day_txt_6 = DayTexture
            set RewardsWidget.button_desc_text_6 = DayDescriptionText
            set RewardsWidget.button_text_6 = DayStatusText
            set RewardsWidget.button_col_6 = DayStatusColor
            set RewardsWidget.button_claimed_6 = DayIsClaimed

    HandleDayClaim(InteractingAgent:agent, Player:player, RewardsWidget:WBP_Daily_Rewards, SelectedDayIndex:int):void =
        PlayerState := GetOrCreatePlayerState(Player)
        CurrentTime := GetSecondsSinceEpoch()
        CanClaimSelectedReward := CanClaimSelectedDay(PlayerState, SelectedDayIndex, CurrentTime)
        if (CanClaimSelectedReward?):
            UpdatedPlayerState := ClaimCurrentDay(Player, PlayerState)
            TriggerClaimForDay(InteractingAgent, SelectedDayIndex)
            RefreshRewardsWidget(UpdatedPlayerState, RewardsWidget)
            Log("DailyRewards: claimed day index {SelectedDayIndex}, total claimed days now {UpdatedPlayerState.ClaimedDays}")
        else:
            Log("DailyRewards: claim rejected for day index {SelectedDayIndex} (not the active/claimable day)")

    CanClaimSelectedDay(PlayerState:reward_player_state, SelectedDayIndex:int, CurrentTime:float)<reads>:logic =
        ActiveDayIndex := GetClaimedDaysInCurrentWindow(PlayerState)
        if (SelectedDayIndex = ActiveDayIndex):
            CanClaimCurrentDay := IsCurrentDayClaimable(PlayerState, CurrentTime)
            if (CanClaimCurrentDay?):
                return true

        false

    ClaimCurrentDay(Player:player, PlayerState:reward_player_state)<transacts>:reward_player_state =
        CurrentTime := GetSecondsSinceEpoch()
        UpdatedPlayerState := reward_player_state:
            Version := DailyRewardsDataVersion
            ClaimedDays := PlayerState.ClaimedDays + 1
            NextClaimAtEpoch := CurrentTime + StatusConfig.ClaimCooldownSeconds
            MakeRewardPlayerState<constructor>(PlayerState)
        if (set PlayerStates[Player] = UpdatedPlayerState):
            return UpdatedPlayerState
        return UpdatedPlayerState

    TriggerClaimForDay(InteractingAgent:agent, DayIndex:int):void =
        if (DayIndex = 0):
            RewardConfig.Day1.ClaimTrigger.Trigger(InteractingAgent)

        if (DayIndex = 1):
            RewardConfig.Day2.ClaimTrigger.Trigger(InteractingAgent)

        if (DayIndex = 2):
            RewardConfig.Day3.ClaimTrigger.Trigger(InteractingAgent)

        if (DayIndex = 3):
            RewardConfig.Day4.ClaimTrigger.Trigger(InteractingAgent)

        if (DayIndex = 4):
            RewardConfig.Day5.ClaimTrigger.Trigger(InteractingAgent)

        if (DayIndex = 5):
            RewardConfig.Day6.ClaimTrigger.Trigger(InteractingAgent)

        if (DayIndex = 6):
            RewardConfig.Day7.ClaimTrigger.Trigger(InteractingAgent)
